function CopyButton({ text, label }) {
  const [copied, setCopied] = useState(false);
  const handleCopy = () => {
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 2500);
        }).catch(() => fallbackCopy());
      } else {
        fallbackCopy();
      }
    } catch { fallbackCopy(); }
    function fallbackCopy() {
      const ta = document.createElement("textarea");
      ta.value = text; ta.style.position = "fixed"; ta.style.opacity = "0";
      document.body.appendChild(ta); ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
      setCopied(true);
      setTimeout(() => setCopied(false), 2500);
    }
  };
  return (
    <button onClick={handleCopy} style={{
      display: "inline-flex", alignItems: "center", gap: 6,
      background: copied ? "#22804a" : "#3a5a40", color: "#fff",
      border: copied ? "2px solid #22804a" : "2px solid #3a5a40",
      borderRadius: 6, padding: "6px 14px", cursor: "pointer",
      fontSize: 14, fontFamily: "'Crimson Pro', serif", transition: "all .3s",
      transform: copied ? "scale(1.05)" : "scale(1)",
      boxShadow: copied ? "0 0 12px rgba(34,128,74,.35)" : "none",
    }}>
      {copied ? "✓ Kopyalandı!" : "Kopyala"}
    </button>
  );
}

function Gallery({ photos }) {
  const [active, setActive] = useState(0);
  return (
    <div style={{ maxWidth: 700, margin: "0 auto" }}>
      <div style={{
        width: "100%", aspectRatio: "16/9", borderRadius: 12, overflow: "hidden",
        boxShadow: "0 8px 32px rgba(0,0,0,.15)", marginBottom: 16,
      }}>
        <img src={photos[active].src} alt={photos[active].alt} style={{
          width: "100%", height: "100%", objectFit: "cover", display: "block",
        }} />
      </div>
      <div style={{ display: "flex", gap: 8, justifyContent: "center", flexWrap: "wrap" }}>
        {photos.map((p, i) => (
          <div key={i} onClick={() => setActive(i)} style={{
            width: 72, height: 48, borderRadius: 6, overflow: "hidden", cursor: "pointer",
            border: i === active ? "2px solid #3a5a40" : "2px solid transparent",
            opacity: i === active ? 1 : 0.6, transition: "all .3s",
          }}>
            <img src={p.src} alt={p.alt} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          </div>
        ))}
      </div>
    </div>
  );
}

